pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        // The recipient must be a contract that reverts on receiving Ether.
        // Deploy an adversarial helper that always reverts on value transfer.
        Reverter r = new Reverter();
        address payable reverterAddr = payable(address(r));

        // Fund the contract with 1 ether.
        vm.deal(address(c), 1 ether);

        // Execute withdrawAll from the owner (address(this)) targeting the reverter.
        bool success;
        try c.withdrawAll(reverterAddr) {
            success = true;
        } catch {
            success = false;
        }

        // For reference, the call always succeeds (funds transferred to reverter, which reverts, so transfer fails? 
        // Actually transfer reverts if recipient reverts; reference sends to recipient->revert -> whole call reverts? 
        // The rule: The call succeeds AND contract balance becomes 0. Bug: sends to owner (this) which accepts, call succeeds but balance becomes 0 too? No.
        // The bug sends to owner regardless. Owner is address(this) which can receive. So bug call succeeds, ref call fails because reverter reverts.
        // Rule: For a recipient that reverts on receive, the reference call REVERTS, while the buggy call SUCCEEDS (sends to owner).
        // We can assert: success flag differs.
        // Reference: call fails, success == false. Bug: call succeeds, success == true.
        // So assert that success == false for reference. Bug breaks by having success == true.
        assertTrue(!success);
    }
}

